import java.io.BufferedInputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }
    }

    static class Fenwick {
        private final long[] tree;

        Fenwick(int n) {
            tree = new long[n + 2];
        }

        void add(int index, long value) {
            for (int i = index; i < tree.length; i += i & -i) {
                tree[i] += value;
            }
        }

        long sum(int index) {
            long result = 0;
            for (int i = index; i > 0; i -= i & -i) {
                result += tree[i];
            }
            return result;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int m = fs.nextInt();

        Fenwick slope = new Fenwick(n);
        Fenwick intercept = new Fenwick(n);
        StringBuilder output = new StringBuilder();

        for (int q = 0; q < m; q++) {
            int type = fs.nextInt();
            int i = fs.nextInt();

            if (type == 3) {
                long a = slope.sum(i);
                long b = intercept.sum(i);
                output.append(a * i + b).append('\n');
            } else {
                int v = fs.nextInt();
                int left, right;
                long a, b;

                if (type == 1) {
                    left = i;
                    right = (int) Math.min(n, (long) i + v - 1);
                    a = -1;
                    b = (long) v + i;
                } else {
                    left = (int) Math.max(1L, (long) i - v + 1);
                    right = i;
                    a = 1;
                    b = (long) v - i;
                }

                slope.add(left, a);
                intercept.add(left, b);
                if (right < n) {
                    slope.add(right + 1, -a);
                    intercept.add(right + 1, -b);
                }
            }
        }

        System.out.print(output);
    }
}
